"""Source-owned fields are validated by ingestion, never generated by a model."""
from datetime import datetime
import hashlib
import json
import re


def fingerprint(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, ensure_ascii=False).encode()).hexdigest()


def history_event(value):
    if not isinstance(value, dict):
        raise ValueError('history event must be an object')
    allowed = {'id', 'text', 'speaker', 'source_at', 'timezone', 'media_refs', 'supersedes'}
    if set(value) - allowed:
        raise ValueError('unknown source fields: ' + ', '.join(sorted(set(value) - allowed)))
    for key, maximum in [('id', 160), ('text', 100000), ('speaker', 160)]:
        if not isinstance(value.get(key), str) or not 1 <= len(value[key].strip()) <= maximum:
            raise ValueError('invalid source ' + key)
    stamp = value.get('source_at')
    if stamp is not None:
        if not isinstance(stamp, str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}(?:T.*)?', stamp):
            raise ValueError('source_at must be an ISO date/time or null')
        datetime.fromisoformat(stamp.replace('Z', '+00:00'))
    zone = value.get('timezone')
    if zone is not None:
        from zoneinfo import ZoneInfo
        if not isinstance(zone, str):
            raise ValueError('timezone must be an IANA name or null')
        ZoneInfo(zone)
    media = value.get('media_refs', [])
    if not isinstance(media, list) or len(media) > 20 or any(not isinstance(x, str) or len(x) > 500 for x in media):
        raise ValueError('invalid media references')
    if value.get('supersedes') is not None and not isinstance(value['supersedes'], str):
        raise ValueError('invalid correction reference')
    return {key: value.get(key) for key in ('id', 'text', 'speaker', 'source_at', 'timezone', 'supersedes')} | {'media_refs': media}


def project_source(row, session_id):
    kind = row.get('type')
    metadata = row.get('metadata') or (row.get('message') or {}).get('metadata') or {}
    if kind == 'source.event':
        source = row['source']
        text, speaker, stamp = source['text'], source['speaker'], source['source_at']
        source_type, external_id = 'historical-dialogue', source['id']
    elif kind == 'message' and row.get('status') == 'completed':
        message = row.get('message', {})
        if message.get('role') not in {'user', 'assistant'}:
            return None
        text, speaker = message.get('content'), message['role']
        stamp = metadata.get('sourceRecordedAt') or row['timestamp']
        source_type, external_id = 'assistant-delivery' if speaker == 'assistant' else 'user-statement', row['id']
        source = {'timezone': metadata.get('timezone'), 'media_refs': []}
    elif kind == 'ambient_observation' and row.get('status') == 'accepted':
        evidence = row.get('evidence') or {}
        if not evidence.get('visibleEvidence'):
            return None
        text = json.dumps({k: evidence.get(k) for k in ('visibleEvidence', 'uncertainties', 'media')}, ensure_ascii=False)
        speaker, stamp = 'observation', evidence.get('capturedAt') or row['timestamp']
        source_type, external_id = 'sampled-observation', row['id']
        source = {'timezone': None, 'media_refs': []}
    else:
        return None
    if not isinstance(text, str) or not text.strip():
        return None
    result = {'sourceId': session_id + ':' + row['id'], 'journalEventId': row['id'],
        'externalId': external_id, 'sessionId': session_id, 'text': text, 'speaker': speaker,
        'kind': source_type, 'sourceAt': stamp, 'receivedAt': row['timestamp'],
        'timezone': source.get('timezone'), 'mediaRefs': source.get('media_refs', []),
        'supersedes': source.get('supersedes'), 'eventTime': None, 'validTime': None,
        'timePrecision': 'unknown' if stamp is None else 'day' if len(stamp) == 10 else 'datetime',
        'extractionStatus': 'not-requested', 'vectorStatus': 'not-indexed'}
    result['sourceHash'] = fingerprint(result)
    return result
